effect.shader:
const float TAU = 6.28318530718;

void main() {
    vec2 uv = acScreenNorm;
    vec2 offset = (uv - center) * vec2(acAspect, 1.0) / max(zoom, 0.01);

    vec2 warped;
    if (direction == 1) {
        // Polar para retangular: X vira ângulo, Y vira raio. Um retângulo
        // desenhado assim se abre em leque.
        float angle = (uv.x - 0.5) * TAU + radians(spin);
        float radius = uv.y * 0.5;
        warped = vec2(cos(angle), sin(angle)) * radius / vec2(acAspect, 1.0) + center;
    } else {
        // Retangular para polar: o ângulo em volta do centro vira a coluna, e a
        // distância vira a linha. A borda de baixo da imagem fecha o círculo.
        float angle = atan(offset.y, offset.x) + radians(spin);
        float radius = length(offset) * 2.0;
        warped = vec2(fract(angle / TAU + 0.5), clamp(radius, 0.0, 1.0));
    }

    vec4 twisted = texture(inputImg, clamp(warped, 0.0, 1.0));
    fragColor = mix(texture(inputImg, uv), twisted, amount);
}
